interface ATMState {                 // State pattern
    void insertCard(ATM atm, Card card);
    void enterPin(ATM atm, int pin);
    void withdraw(ATM atm, int amount);
}

class ATM {                          // Singleton controller
    private static final ATM INSTANCE = new ATM();
    private ATMState state = new IdleState();
    private final CashDispenser dispenser = new CashDispenser();
    private ATM() {}
    static ATM getInstance() { return INSTANCE; }
    void setState(ATMState s) { this.state = s; }
    CashDispenser dispenser() { return dispenser; }
    // every action delegates to the current state
    void insertCard(Card c) { state.insertCard(this, c); }
    void withdraw(int amt)  { state.withdraw(this, amt); }
}

class IdleState implements ATMState {
    public void insertCard(ATM atm, Card card) { atm.setState(new CardInsertedState(card)); }
    public void enterPin(ATM atm, int pin)   { throw new IllegalStateException("Insert card first"); }
    public void withdraw(ATM atm, int amount){ throw new IllegalStateException("Insert card first"); }
}
```
*Each state implements only what's valid; invalid actions throw `IllegalStateException` instead of corrupting state.*

