class AuthService {
    private final BankServer bank;
    private int attempts = 0;
    private static final int MAX_ATTEMPTS = 3;

    boolean verify(Card card, int pin) {
        if (card.isLocked()) throw new IllegalStateException("Card locked");
        boolean ok = bank.verifyPin(card.number(), pin); // PIN sent over TLS, never stored
        if (!ok && ++attempts >= MAX_ATTEMPTS) {
            card.lock();                                   // retain/lock after 3 tries
            AuditLog.record("CARD_LOCKED", card.number());
        }
        if (ok) attempts = 0;
        return ok;
        // note: pin is a local int -> eligible for GC; we never keep a field for it
    }
}
```
*The PIN lives only as a method argument and is discarded — there is no `pin` field anywhere.*

