interface WithdrawalPolicy { boolean allows(int amount, double balance); }   // Strategy

class SavingsPolicy implements WithdrawalPolicy {
    public boolean allows(int amount, double balance) { return amount <= 25000 && amount <= balance; }
}
class CheckingPolicy implements WithdrawalPolicy {
    public boolean allows(int amount, double balance) { return amount <= balance + 10000; } // overdraft
}

class ATM {                       // Facade over subsystems
    private final CardReader reader;
    private final CashDispenser dispenser;
    private final BankServer bank;
    // one simple call hides reader + bank + dispenser coordination
    void withdraw(Account acc, int amount) {
        if (!acc.policy().allows(amount, acc.balance())) throw new IllegalStateException("Limit");
        bank.debit(acc, amount);
        dispenser.dispense(amount);
    }
}
